enum StatusTarefa { Pendente, EmAndamento, Concluida }
interface Tarefa {
  id: number;
  titulo: string;
  status: StatusTarefa;
}
class GerenciadorTarefas {
  private tarefas: Tarefa[] = [];
  adicionar(titulo: string): Tarefa {
    const nova: Tarefa = { id: this.tarefas.length + 1, titulo, status: StatusTarefa.Pendente };
    this.tarefas.push(nova);
    return nova;
  }
}

class Repositorio<T extends { id: number }> {
  private itens: T[] = [];
  adicionar(item: T): void {
    this.itens.push(item);
  }
  buscarPorId(id: number): T | undefined {
    return this.itens.find((i) => i.id === id);
  }
}

